using DriveOS.SharedKernel.Domain;using DriveOS.SharedKernel.Identifiers;using DriveOS.SharedKernel.Results;using DriveOS.Modules.Students.Domain.Events;
namespace DriveOS.Modules.Students.Domain.ExternalTransfers;
public sealed class ExternalTransferCase:AggregateRoot<ExternalTransferCaseId>{private readonly List<StudentDataGrant> dataGrants=[];private readonly List<ExternalTransferAuditEntry> audit=[];private ExternalTransferCase(){}private ExternalTransferCase(ExternalTransferCaseId id,OrganizationId source,OrganizationId target,PersonId student,ExternalTransferType type,ExternalTransferDataScope scope,DateOnly effectiveOn,DateOnly? temporaryUntil,string country,string reason,string responsibilities,UserId actor,DateTimeOffset now):base(id){SourceOrganizationId=source;TargetOrganizationId=target;StudentId=student;Type=type;DataScope=scope;EffectiveOn=effectiveOn;TemporaryUntil=temporaryUntil;CountryCode=country;Reason=reason;Responsibilities=responsibilities;Status=ExternalTransferStatus.ConsentPending;ConsentStatus=TransferConsentStatus.Pending;FinancialStatus=TransferFinancialStatus.Pending;CreatedByUserId=actor;CreatedAtUtc=now;audit.Add(ExternalTransferAuditEntry.Create(id,"Created",reason,actor,now));RaiseDomainEvent(new StudentAggregateChangedDomainEvent<ExternalTransferCaseId>(Id,StudentId,SourceOrganizationId,"Created"));}public OrganizationId SourceOrganizationId{get;private set;}public OrganizationId TargetOrganizationId{get;private set;}public PersonId StudentId{get;private set;}public ExternalTransferType Type{get;private set;}public ExternalTransferDataScope DataScope{get;private set;}public DateOnly EffectiveOn{get;private set;}public DateOnly? TemporaryUntil{get;private set;}public string CountryCode{get;private set;}=string.Empty;public string Reason{get;private set;}=string.Empty;public string Responsibilities{get;private set;}=string.Empty;public ExternalTransferStatus Status{get;private set;}public TransferConsentStatus ConsentStatus{get;private set;}public string? ConsentEvidenceReference{get;private set;}public DateTimeOffset? ConsentVerifiedAtUtc{get;private set;}public TransferFinancialStatus FinancialStatus{get;private set;}public string? FinancialResolution{get;private set;}public TargetRelationshipStatus RelationshipStatus{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public UserId CreatedByUserId{get;private set;}public DateTimeOffset? CompletedAtUtc{get;private set;}public IReadOnlyCollection<StudentDataGrant> DataGrants=>dataGrants;public IReadOnlyCollection<ExternalTransferAuditEntry> Audit=>audit;
 public static Result<ExternalTransferCase>Create(OrganizationId source,OrganizationId target,PersonId student,ExternalTransferType type,ExternalTransferDataScope scope,DateOnly effectiveOn,DateOnly? temporaryUntil,string country,string reason,string responsibilities,UserId actor,DateTimeOffset now){if(source.IsEmpty||target.IsEmpty||student.IsEmpty)return Result.Failure<ExternalTransferCase>(ExternalTransferErrors.InvalidOwner);if(source==target)return Result.Failure<ExternalTransferCase>(ExternalTransferErrors.SameOrganization);if(scope==ExternalTransferDataScope.None||effectiveOn<DateOnly.FromDateTime(now.UtcDateTime)||string.IsNullOrWhiteSpace(country)||string.IsNullOrWhiteSpace(reason)||string.IsNullOrWhiteSpace(responsibilities)||type==ExternalTransferType.TemporaryTransfer&&(!temporaryUntil.HasValue||temporaryUntil.Value<=effectiveOn))return Result.Failure<ExternalTransferCase>(ExternalTransferErrors.InvalidRequest);return Result.Success(new ExternalTransferCase(ExternalTransferCaseId.New(),source,target,student,type,scope,effectiveOn,temporaryUntil,country.Trim().ToUpperInvariant(),reason.Trim(),responsibilities.Trim(),actor,now));}
 public Result VerifyConsent(string evidence,UserId actor,DateTimeOffset now){if(Status!=ExternalTransferStatus.ConsentPending||string.IsNullOrWhiteSpace(evidence))return Result.Failure(ExternalTransferErrors.InvalidTransition);ConsentStatus=TransferConsentStatus.Verified;ConsentEvidenceReference=evidence.Trim();ConsentVerifiedAtUtc=now;audit.Add(ExternalTransferAuditEntry.Create(Id,"ConsentVerified",evidence,actor,now));RaiseDomainEvent(new StudentAggregateChangedDomainEvent<ExternalTransferCaseId>(Id,StudentId,SourceOrganizationId,"ConsentVerified"));return Result.Success();}
 public Result ReviewFinance(TransferFinancialStatus status,string? resolution,UserId actor,DateTimeOffset now){if(status==TransferFinancialStatus.Pending||((status is TransferFinancialStatus.ResolutionRequired or TransferFinancialStatus.Resolved)&&string.IsNullOrWhiteSpace(resolution)))return Result.Failure(ExternalTransferErrors.InvalidRequest);FinancialStatus=status;FinancialResolution=resolution?.Trim();audit.Add(ExternalTransferAuditEntry.Create(Id,"FinanceReviewed",status.ToString(),actor,now));return Result.Success();}
 public Result Submit(TargetRelationshipStatus relationship,UserId actor,DateTimeOffset now){if(ConsentStatus!=TransferConsentStatus.Verified)return Result.Failure(ExternalTransferErrors.ConsentRequired);if(FinancialStatus is TransferFinancialStatus.Pending or TransferFinancialStatus.ResolutionRequired)return Result.Failure(ExternalTransferErrors.FinancialReviewRequired);if(relationship==TargetRelationshipStatus.Missing)return Result.Failure(ExternalTransferErrors.RelationshipRequired);RelationshipStatus=relationship;Status=ExternalTransferStatus.TargetReview;audit.Add(ExternalTransferAuditEntry.Create(Id,"Submitted",relationship.ToString(),actor,now));RaiseDomainEvent(new StudentAggregateChangedDomainEvent<ExternalTransferCaseId>(Id,StudentId,SourceOrganizationId,"Submitted"));return Result.Success();}
 public Result Decide(bool accept,string reason,UserId actor,DateTimeOffset now){if(Status!=ExternalTransferStatus.TargetReview||string.IsNullOrWhiteSpace(reason))return Result.Failure(ExternalTransferErrors.InvalidTransition);Status=accept?(EffectiveOn>DateOnly.FromDateTime(now.UtcDateTime)?ExternalTransferStatus.Scheduled:ExternalTransferStatus.InProgress):ExternalTransferStatus.Rejected;if(accept)dataGrants.Add(StudentDataGrant.Create(Id,TargetOrganizationId,DataScope,now,Type==ExternalTransferType.TemporaryTransfer?TemporaryUntil:null));audit.Add(ExternalTransferAuditEntry.Create(Id,accept?"Accepted":"Rejected",reason,actor,now));RaiseDomainEvent(new StudentAggregateChangedDomainEvent<ExternalTransferCaseId>(Id,StudentId,SourceOrganizationId,accept?"Accepted":"Rejected"));return Result.Success();}
 public Result Complete(UserId actor,DateTimeOffset now){if(Status is not ExternalTransferStatus.Accepted and not ExternalTransferStatus.Scheduled and not ExternalTransferStatus.InProgress)return Result.Failure(ExternalTransferErrors.InvalidTransition);Status=ExternalTransferStatus.Completed;CompletedAtUtc=now;audit.Add(ExternalTransferAuditEntry.Create(Id,"Completed",Reason,actor,now));RaiseDomainEvent(new StudentAggregateChangedDomainEvent<ExternalTransferCaseId>(Id,StudentId,SourceOrganizationId,"Completed"));return Result.Success();}
 public void RevokeActiveDataGrants(UserId actor,DateTimeOffset now){foreach(var grant in dataGrants.Where(x=>x.IsActive(DateOnly.FromDateTime(now.UtcDateTime))))grant.Revoke(now);audit.Add(ExternalTransferAuditEntry.Create(Id,"DataGrantsRevoked","Enrollment closure",actor,now));}}
public sealed class StudentDataGrant{private StudentDataGrant(){}public Guid Id{get;private set;}public ExternalTransferCaseId ExternalTransferCaseId{get;private set;}public OrganizationId GranteeOrganizationId{get;private set;}public ExternalTransferDataScope Scope{get;private set;}public DateTimeOffset GrantedAtUtc{get;private set;}public DateOnly? ExpiresOn{get;private set;}public DateTimeOffset? RevokedAtUtc{get;private set;}internal static StudentDataGrant Create(ExternalTransferCaseId transfer,OrganizationId target,ExternalTransferDataScope scope,DateTimeOffset now,DateOnly? expires)=>new(){Id=Guid.NewGuid(),ExternalTransferCaseId=transfer,GranteeOrganizationId=target,Scope=scope,GrantedAtUtc=now,ExpiresOn=expires};public bool IsActive(DateOnly today)=>RevokedAtUtc is null&&(!ExpiresOn.HasValue||ExpiresOn.Value>=today);internal void Revoke(DateTimeOffset now){RevokedAtUtc=now;ExpiresOn=DateOnly.FromDateTime(now.UtcDateTime);}}
public sealed class ExternalTransferAuditEntry{private ExternalTransferAuditEntry(){}public Guid Id{get;private set;}public ExternalTransferCaseId ExternalTransferCaseId{get;private set;}public string Action{get;private set;}=string.Empty;public string Detail{get;private set;}=string.Empty;public UserId ActorUserId{get;private set;}public DateTimeOffset OccurredAtUtc{get;private set;}internal static ExternalTransferAuditEntry Create(ExternalTransferCaseId transfer,string action,string detail,UserId actor,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),ExternalTransferCaseId=transfer,Action=action,Detail=detail,ActorUserId=actor,OccurredAtUtc=now};}
